//! The CSSOM-View element metrics Chrome 156 control
//! (`tests/fixtures/cssom_metrics_chrome156.json`, generated by turbo-dom's
//! `scripts/cssom-metrics-chrome-control.mjs`): every case is laid out through the live
//! HTML snapshot as turbo-surf takes it (`testing::layout_with`, surf's UA supplement),
//! and each `[data-cid]` element is read the way surf's CSSOM-View glue reads it —
//! `offsetLeft`/`offsetTop`/`offsetParent` from [`metrics::offset_position`], the boxes,
//! client rects, `offsetWidth`/`offsetHeight` and `client*` from
//! [`metrics::element_geometry`] (falling back to [`inline::geometry`] for a flattened
//! plain inline) — and compared with Chrome's. A case's `hits` are hit tested like
//! `document.elementsFromPoint` ([`hit::elements_at_point`], no scroll offsets) and the
//! whole topmost-first list is compared.
use std::collections::BTreeMap;

use serde_json::Value;

use crate::cssom_view::{hit, inline, metrics};
use crate::layout_snapshot::{LayoutSnapshot, Rect, SourceId};
use crate::live::source_id;
use crate::live::testing::{layout_with, DOCUMENT};

const FIXTURE: &str = include_str!("../../tests/fixtures/cssom_metrics_chrome156.json");

/// The flattened-inline error the glue answers with the inline seam instead.
const NO_BORDER_BOX: &str =
    "native live layout requires inline border/cluster provenance for this element";

fn css_of(html: &str) -> &str {
    html.split_once("<style>")
        .and_then(|(_, rest)| rest.split_once("</style>"))
        .map_or("", |(css, _)| css)
}

/// The `data-cid` (else the local name) of the element whose source is `id`.
fn cid_of(tree: &turbo_dom::Tree, id: SourceId) -> Option<String> {
    let handle = tree.handles().find(|&h| source_id(DOCUMENT, h) == id)?;
    tree.get_attribute_local(handle, "data-cid")
        .or_else(|| tree.local_name(handle))
        .map(str::to_string)
}

fn rect_of(value: &Value) -> Rect {
    let n = |i: usize| value[i].as_f64().unwrap() as f32;
    Rect {
        x: n(0),
        y: n(1),
        width: n(2),
        height: n(3),
    }
}

fn close(a: Rect, b: Rect) -> bool {
    [
        (a.x, b.x),
        (a.y, b.y),
        (a.width, b.width),
        (a.height, b.height),
    ]
    .iter()
    .all(|(a, b)| (a - b).abs() <= 0.01)
}

fn geometry(
    snapshot: &LayoutSnapshot,
    styles: &crate::cssom_view::scroll::SourceStyles,
    id: SourceId,
) -> Result<metrics::ElementGeometry, String> {
    // As surf's glue (`live_layout_backend::element_geometry`): a `display: contents`
    // element has no boxes, and the root's client area is the viewport (CSSOM View
    // §6.1 `clientWidth`/`clientHeight` of the document element).
    let style = &styles[&id];
    if style.style.get("display") == Some("contents") {
        return Ok(metrics::empty_geometry());
    }
    let mut geometry = match metrics::element_geometry(snapshot, id) {
        Err(error) if error == NO_BORDER_BOX => inline::geometry(snapshot, styles, id),
        result => result,
    }?;
    if style.parent.is_none() {
        let (width, height) = snapshot.viewport();
        geometry.client.width = width as i32;
        geometry.client.height = height as i32;
    }
    Ok(geometry)
}

fn check_case(case: &Value, failures: &mut Vec<String>) -> usize {
    let name = case["id"].as_str().unwrap();
    let html = case["html"].as_str().unwrap();
    let (tree, snapshot, styles) =
        layout_with(html, css_of(html), (1280.0, 800.0), Some(1.0), |_| {});
    let mut compared = 0;
    for want in case["boxes"].as_array().unwrap() {
        let cid = want["cid"].as_str().unwrap();
        let label = format!("{name}: {cid}");
        let id = source_id(
            DOCUMENT,
            tree.query_selector(&format!("[data-cid=\"{cid}\"]"))
                .unwrap(),
        );
        compared += 1;
        match geometry(&snapshot, &styles, id) {
            Err(error) => failures.push(format!("{label} geometry failed: {error}")),
            Ok(got) => {
                let bounds = rect_of(&want["bounds"]);
                if !close(got.bounds, bounds) {
                    failures.push(format!("{label} bounds {:?}, Chrome {bounds:?}", got.bounds));
                }
                let rects: Vec<Rect> = want["rects"].as_array().unwrap().iter().map(rect_of).collect();
                if got.rects.len() != rects.len()
                    || got.rects.iter().zip(&rects).any(|(a, b)| !close(*a, *b))
                {
                    failures.push(format!("{label} rects {:?}, Chrome {rects:?}", got.rects));
                }
                let client = [got.client.left, got.client.top, got.client.width, got.client.height];
                let chrome: Vec<i64> = want["client"].as_array().unwrap().iter().map(|v| v.as_i64().unwrap()).collect();
                if client.iter().map(|&v| i64::from(v)).collect::<Vec<_>>() != chrome {
                    failures.push(format!("{label} client {client:?}, Chrome {chrome:?}"));
                }
                let size = [i64::from(got.offset.width), i64::from(got.offset.height)];
                let offset: Vec<i64> = want["offset"].as_array().unwrap().iter().map(|v| v.as_i64().unwrap()).collect();
                if size[..] != offset[2..] {
                    failures.push(format!("{label} offset size {size:?}, Chrome {:?}", &offset[2..]));
                }
            }
        }
        match metrics::offset_position(&snapshot, &styles, id) {
            Err(error) => failures.push(format!("{label} offset_position failed: {error}")),
            Ok(got) => {
                let offset: Vec<i64> = want["offset"].as_array().unwrap().iter().map(|v| v.as_i64().unwrap()).collect();
                let parent = got.parent.and_then(|p| cid_of(&tree, p));
                if [i64::from(got.left), i64::from(got.top)][..] != offset[..2]
                    || parent.as_deref() != want["parent"].as_str()
                {
                    failures.push(format!(
                        "{label} offset ({}, {}, {parent:?}), Chrome ({}, {}, {})",
                        got.left, got.top, offset[0], offset[1], want["parent"]
                    ));
                }
            }
        }
    }
    for want in case["hits"].as_array().into_iter().flatten() {
        let point = [want["x"].as_f64().unwrap(), want["y"].as_f64().unwrap()];
        let chrome: Vec<Option<String>> = want["hits"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().map(str::to_string))
            .collect();
        compared += 1;
        match hit::elements_at_point(&snapshot, &styles, &BTreeMap::new(), point) {
            Err(error) => failures.push(format!("{name}: hits{point:?} failed: {error}")),
            Ok(ids) => {
                let got: Vec<Option<String>> = ids.iter().map(|&id| cid_of(&tree, id)).collect();
                if got != chrome {
                    failures.push(format!("{name}: hits{point:?} = {got:?}, Chrome {chrome:?}"));
                }
            }
        }
    }
    compared
}

#[test]
fn element_metrics_and_hits_match_chrome_156() {
    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();
    assert!(fixture["chrome"].as_str().unwrap().starts_with("156."));
    let mut failures = Vec::new();
    let mut compared = 0;
    for case in fixture["cases"].as_array().unwrap() {
        compared += check_case(case, &mut failures);
    }
    assert!(compared > 80, "{compared}");
    assert!(
        failures.is_empty(),
        "{} CSSOM-View reads differ from Chrome 156:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
